<?php require_once __DIR__.'/../config/db.php';$pageTitle='Pending Tutors';require __DIR__.'/includes/admin_layout_start.php';$tutors=[];try{$stmt=db()->query("SELECT id,full_name,email,phone,created_at FROM users WHERE role='tutor' AND is_verified=0 AND is_suspended=0 AND rejection_reason IS NULL ORDER BY created_at ASC");$tutors=$stmt->fetchAll();}catch(Throwable $e){} ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Pending tutors</h1><p class="text-secondary mb-0">Review applications before tutors appear publicly.</p></div><span class="badge text-bg-warning"><?=count($tutors)?> awaiting review</span></div><?php if($m=flash('admin_success')):?><div class="alert alert-success"><?=e($m)?></div><?php endif;?><?php if($m=flash('admin_error')):?><div class="alert alert-danger"><?=e($m)?></div><?php endif;?><div class="admin-table table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Registered</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($tutors as $t):?><tr id="tutor-<?=e((string)$t['id'])?>"><td class="fw-semibold"><?=e($t['full_name'])?></td><td><?=e($t['email'])?></td><td><?=e($t['phone'])?></td><td><?=e(date('d M Y',strtotime($t['created_at'])))?></td><td class="text-end"><form class="d-inline" method="post" action="actions.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="approve_tutor"><input type="hidden" name="id" value="<?=e((string)$t['id'])?>"><input type="hidden" name="redirect" value="pending_tutors.php"><button class="btn btn-sm btn-brand">Approve</button></form><button class="btn btn-sm btn-outline-danger ms-1" data-bs-toggle="modal" data-bs-target="#rejectModal" data-id="<?=e((string)$t['id'])?>" data-name="<?=e($t['full_name'])?>">Reject</button></td></tr><?php endforeach;?><?php if(!$tutors):?><tr><td colspan="5" class="text-center text-secondary py-5">No tutor applications need review.</td></tr><?php endif;?></tbody></table></div><div class="modal fade" id="rejectModal" tabindex="-1"><div class="modal-dialog"><form class="modal-content" method="post" action="actions.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reject_tutor"><input type="hidden" name="id" id="rejectId"><input type="hidden" name="redirect" value="pending_tutors.php"><div class="modal-header"><h5 class="modal-title">Reject application</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p id="rejectText"></p><label class="form-label">Reason</label><textarea class="form-control" name="reason" required minlength="3" maxlength="1000"></textarea><small class="text-secondary">The account is retained with this reason for a clear audit trail.</small></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger">Reject tutor</button></div></form></div></div><script>document.getElementById('rejectModal').addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;document.getElementById('rejectId').value=b.dataset.id;document.getElementById('rejectText').textContent=`Provide a reason for rejecting ${b.dataset.name}'s application.`});</script><?php require __DIR__.'/includes/admin_layout_end.php'; ?>
